/** @jest-environment node */

const {
  resolveTargetEnvironment,
  shouldUseDraftValues,
} = require('../resolveTargetEnvironment');

describe('resolveTargetEnvironment', () => {
  const originalEnv = process.env;

  beforeEach(() => {
    process.env = { ...originalEnv };
    delete process.env.TRANSLATIONS_TARGET_ENV;
    delete process.env.DEPLOY_ENV;
    delete process.env.ENVIRONMENT;
  });

  afterAll(() => {
    process.env = originalEnv;
  });

  it('reads TRANSLATIONS_TARGET_ENV first', () => {
    process.env.TRANSLATIONS_TARGET_ENV = ' PROD ';
    expect(resolveTargetEnvironment()).toBe('prod');
  });

  it('falls back to DEPLOY_ENV', () => {
    process.env.DEPLOY_ENV = 'uat';
    expect(resolveTargetEnvironment()).toBe('uat');
  });

  it('falls back to ENVIRONMENT', () => {
    process.env.ENVIRONMENT = 'sit';
    expect(resolveTargetEnvironment()).toBe('sit');
  });

  it('returns empty string when no env is set', () => {
    expect(resolveTargetEnvironment()).toBe('');
  });
});

describe('shouldUseDraftValues', () => {
  it('returns true for sit', () => {
    expect(shouldUseDraftValues('sit')).toBe(true);
  });

  it('returns false for uat', () => {
    expect(shouldUseDraftValues('uat')).toBe(false);
  });

  it('returns true for empty environment (local dev)', () => {
    expect(shouldUseDraftValues('')).toBe(true);
  });

  it('returns false for prod', () => {
    expect(shouldUseDraftValues('prod')).toBe(false);
  });
});
